// Table of -log2(R[i]) represented in triple-double precision {lo, mid, hi},
// where R[i] = 2^-8 * ceil(2^8 * (1 - 2^-8) / (1 + i * 2^-7)) for i = 0..127.
//
// The least significant bit of the high part `hi` is chosen to be >= 2^-20,
// so that the total precision of (e_x + hi) is at most 8 + 20 = 28 bits
// (since |e_x| <= 150 < 2^8 fits in 8 bits).
// Because the single-precision exponent y has 24 bits of mantissa, the product
// y * (e_x + hi) spans at most 24 + 28 = 52 bits <= 53 bits, making it exact
// in double precision.
// The mid part provides 53 bits for fast evaluation, and the lo part provides
// another 53 bits for the accurate fallback, yielding >= 127 bits of precision.
//
// Generated by Sollya with:
// > display = hexadecimal;
// > prec = 200;
// > for i from 0 to 127 do {
//     if (i == 0) then {
//       print("{0.0, 0.0, 0.0},");
//     } else if (i == 127) then {
//       print("{0.0, 0.0, 1.0},");
//     } else {
//       r = 2^(-8) * ceil( 2^8 * (1 - 2^(-8)) / (1 + i*2^(-7)) );
//       l = -log2(r);
//       h = nearestint(l * 2^20) * 2^(-20);
//       m = round(l - h, D, RN);
//       lo = round(l - h - m, D, RN);
//       print("{", lo, ", ", m, ", ", h, "},");
//     };
//   };
