// Lookup table for 5-bit (32 entries) range reduction for float_eval and
// double_eval fast path:
//   r(0) = 1.0f
//   r(i) = 2^-6 * ceil(2^6 * (1 - 2^-6) / (1 + i * 2^-5)), i = 1..31.
// The constants are chosen so that dx = r * m_x - 1 is exact in
// single precision (with hardware FMA or 14-bit Sterbenz split), and
// -2^-6 <= dx < 2^-5.
//
// Generated by Sollya with:
// > display = hexadecimal;
// > for i from 0 to 31 do {
//     if (i == 0) then {
//       print("0x1.0p+0f,");
//     } else {
//       r = 2^(-6) * ceil( 2^6 * (1 - 2^(-6)) / (1 + i*2^(-5)) );
//       print(r @ "f,");
//     };
//   };
